// 原条件折叠的纯域门；不构造World，不把typed源代作完整供给或驻地验证。
#include "resident/domains/military/military_garrison_rest.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool value,const char* why){++checks;if(!value)throw std::runtime_error(why);}template<class T>T take(Outcome<T> r){if(!r.ok)throw std::runtime_error(r.error.original.code);return r.value;}}
int main(){try{
 MilitaryCatalog cat;GarrisonDefinition camp;camp.id="camp";MilitaryUnitDefinition definition;definition.id="unit";definition.initial_training=40;definition.initial_fatigue=25;camp.units={definition};cat.garrisons={camp};cat.garrison_rest_policy=MilitaryGarrisonRestPolicy{};MilitaryState m;MilitaryUnitRecord unit;unit.id="unit";unit.source_garrison_id="camp";unit.fit={"soldier:unit:1"};unit.training=40;unit.fatigue=25;m.military_units={unit};
 MilitaryGarrisonRestFact first;first.id="military_rest:2";first.unit_id="unit";first.garrison_id="camp";first.organization_id="org";first.supply_fact_id="military:1";first.tick=1;first.training=40;first.fatigue_before=25;first.fatigue_after=15;m.garrison_rest.facts={first};check(validate_military_garrison_rest_shape(m.garrison_rest).ok,"fixed real fatigue difference shape");auto condition=take(fold_military_condition(m,cat,"unit",1));check(condition.training==40&&condition.fatigue==15,"rest changes fatigue only");check(take(fold_military_condition_before_period(m,cat,"unit",1)).fatigue==25,"period start excludes its result");
 MilitaryMarchFact march;march.id="military:3";march.tick=2;march.units.push_back({"unit",40,15,18,{}});m.march_facts={march};MilitaryGarrisonRestFact last=first;last.id="military_rest:5";last.supply_fact_id="military:4";last.tick=3;last.fatigue_before=18;last.fatigue_after=8;m.garrison_rest.facts.push_back(last);condition=take(fold_military_condition(m,cat,"unit",3));check(condition.fatigue==8&&condition.training==40,"actual rest march rest single chain");check(take(fold_military_condition_before_period(m,cat,"unit",2)).fatigue==15,"later march and rest do not alter earlier boundary");check(!fold_military_condition(m,cat,"unit",2).ok,"stable full reader rejects future fact");
 auto good=m;m.garrison_rest.facts[1].fatigue_before=28;m.garrison_rest.facts[1].fatigue_after=18;check(!fold_military_condition(m,cat,"unit",3).ok,"self-consistent record cannot replace actual before chain");m=good;m.garrison_rest.facts[1].tick=2;check(!fold_military_condition(m,cat,"unit",3).ok,"same period march and rest cannot both happen");m=good;m.garrison_rest.facts[1].fatigue_after=9;check(!validate_military_garrison_rest_shape(m.garrison_rest).ok,"wrong fatigue delta rejected");m=good;m.garrison_rest.facts[1].fatigue_before=5;m.garrison_rest.facts[1].fatigue_after=0;check(validate_military_garrison_rest_shape(m.garrison_rest).ok,"floor zero shape");m.garrison_rest.facts[1].fatigue_before=0;check(!validate_military_garrison_rest_shape(m.garrison_rest).ok,"zero effect source rejected");m=good;cat.garrison_rest_policy.reset();check(!fold_military_condition(m,cat,"unit",3).ok,"old profile rejects hidden recovery");check(m.military_units[0].fit==unit.fit&&m.military_units[0].training==unit.training,"fold is read only and conserves roster");
 std::cout<<"MILITARY_GARRISON_REST_CONDITION="<<checks<<" FAILURES=0 SCOPE=PURE_CONDITION_COMPONENT\n";return 0;
 }catch(const std::exception& e){std::cerr<<"MILITARY_GARRISON_REST_CONDITION_FAIL "<<checks<<" "<<e.what()<<'\n';return 1;}}
